pub fn game_string<R:Real>(ctx:&Ctx<R>) -> String {
    let mut s=String::new();let o=&ctx.character.primary;let p="character.";
    characterb2d(&mut s,p,ctx,o);
    match o.kind {
        1=>wheelchairguy(&mut s,p,ctx,o),2=>segwayguy(&mut s,p,ctx,o),
        3=>{bicycleguy(&mut s,p,ctx,o);irresponsibledad(&mut s,p,ctx,o);
            characterb2d(&mut s,"child.",ctx,&ctx.character.child);childseatkid(&mut s,"child.",ctx,&ctx.character.child);},
        4=>motorcart(&mut s,p,ctx,o),_=>panic!("unknown character"),
    }
    s
}
